@startuml

class Customer {
  + VATNumber : string
  + Name : string
  + PhoneNumber : string
  + Address : string
}

class Package {
  + IdentifierCode : string
  + Weight : float
  + Urgency : string
}

class DeliveryCenter {
  + Name : string
  + Address : string
}

class Courier {
  + VATNumber : string
  + Name : string
  + PhoneNumber : string
}

Customer "1" -- "0..*" Package : sends
Customer "1" -- "0..*" Package : receives
Customer "1" -- "0..1" DeliveryCenter : is associated with
Package "0..*" -- "1" DeliveryCenter : is delivered to
Package "0..*" -- "1" DeliveryCenter : is routed through
Courier "1" -- "0..*" Package : is assigned to
Courier "1" -- "1" DeliveryCenter : works in

@enduml

